+package com.example.data;
+
+import java.time.Instant;
+import java.util.Collections;
+import java.util.LinkedList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * In-memory store of contact messages, shared across all views and visits
+ * for as long as the application is running.
+ */
+@Service
+public class ContactMessageService {
+
+    private final List<ContactMessage> messages = new LinkedList<>();
+
+    public synchronized ContactMessage send(String name, String email, String phone, String message) {
+        var contactMessage = new ContactMessage(name, email, phone, message, Instant.now());
+        messages.addFirst(contactMessage);
+        return contactMessage;
+    }
+
+    public synchronized List<ContactMessage> findAll() {
+        return Collections.unmodifiableList(new LinkedList<>(messages));
+    }
+}
