+package com.example.views.contact;
+
+import com.example.data.ContactMessage;
+import com.example.data.ContactMessageService;
+import com.example.views.about.AboutView;
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationVariant;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final ContactMessageService service;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        sendButton.addClickListener(event -> trySend());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        for (var field : new HasValue<?, ?>[] { name, email, phone, message }) {
+            field.addValueChangeListener(event -> {
+                if (event.isFromClient()) {
+                    sendButton.setEnabled(true);
+                }
+            });
+        }
+
+        var form = new VerticalLayout(name, email, phone, message, sendButton);
+        form.setPadding(false);
+        add(form);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void trySend() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        boolean valid = true;
+
+        if (nameValue.isEmpty()) {
+            name.setInvalid(true);
+            name.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        if (!emailValue.isEmpty() && isInvalidEmail(emailValue)) {
+            email.setInvalid(true);
+            email.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (messageValue.isEmpty()) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        service.send(nameValue, emailValue, phoneValue, messageValue);
+        refreshGrid();
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+
+        sendButton.setEnabled(false);
+
+        var notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+    }
+
+    private boolean isInvalidEmail(String value) {
+        return new EmailValidator("invalid").apply(value, new ValueContext()).isError();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(service.findAll());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty() || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedInput()) {
+            var action = event.postpone();
+            confirmNavigation(action);
+        }
+    }
+
+    private void confirmNavigation(BeforeLeaveEvent.ContinueNavigationAction action) {
+        var dialog = new Dialog();
+        dialog.add("You have unsaved input. Leave anyway and discard it?");
+
+        var keepEditing = new Button("Keep editing", event -> {
+            dialog.close();
+            action.cancel();
+        });
+        var discard = new Button("Discard", event -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
